import React, { useContext, useState } from 'react'
import context from '../context/Notecontext'
import Alert from './Alert';

const Addnote = () => {
    const Context = useContext(context);
    const { addnote } = Context

    const [note, setnote] = useState({ title: "", description: "", tag: "" })

    const handleclick = (e) => {
        e.preventDefault();
        addnote(note.title, note.description, note.tag);
        <Alert/>
        setnote({ title: "", description: "", tag: "" })
    }
    const onChange = (e) => {
        setnote({ ...note, [e.target.name]: e.target.value })
    }
    return (
        <div>
            <div className='container mt-2'>
                <h2>Add a Note</h2>
                <div className="mb-3 my-1">
                    <label htmlFor="title" className="form-label">Title</label>
                    <input type="text" className="form-control" id="title" name='title' style={{ "width": "300px" }} value={note.title} onChange={onChange} />
                </div>
                <div className="col-auto my-2">
                    <label htmlFor="description">Description</label>
                    <input type="text" className="form-control" id="description" name='description' style={{ "width": "300px" }} value={note.description} onChange={onChange} />
                </div>
                <div className="col-auto my-2">
                    <label htmlFor="tag">Tag</label>
                    <input type="text" className="form-control" id="tag" name='tag' style={{ "width": "300px" }} value={note.tag} onChange={onChange} />
                </div>
                <div className="col-auto mt-3">
                    <button disabled={note.title.length < 5 || note.description.length < 5} type="submit" alert={alert} className="btn btn-info mb-3" onClick={handleclick}>Add Note</button>
                </div>
            </div>

        </div>
    )
}

export default Addnote
